function connect(v){if(session?.room!==v.code)$('chatInput').value='';stream?.close();stopSearch();$('matchDialog').close();lobbyTimerPending=null;lastChatKey="!";$('chatButton').classList.remove('has-unread');clearTimeout(botTimer);epoch++;local=false;game=null;lastRevision=0;lastCelebrated=0;finishedRevision=0;session={room:v.code,token:v.token};const saved=openGames().find(g=>g.room===v.code);pending=saved?.draft||[];handOrder=saved?.order||[];save('renkio-session',session);try{sessionStorage.setItem('renkio-session',JSON.stringify(session))}catch{}$('resume').classList.remove('hidden');receive(v);subscribe()}
