function subscribe(){stream?.close();const generation=epoch;connection(false);stream=new EventSource(`/api/events?room=${session.room}&token=${session.token}`);stream.onopen=()=>{if(generation===epoch)connection(true)};stream.onmessage=e=>{if(generation!==epoch)return;try{receive(JSON.parse(e.data));connection(true)}catch(error){console.error('Masa güncellemesi okunamadı',error.message)}};stream.onerror=()=>{if(generation===epoch)connection(false)}}
function receive(v){serverOffset=(v.serverNow||Date.now())-Date.now();room=v;me=v.me;rememberCompleted(v);rememberRoom(v);renderChat();if(v.game){const next=v.game,initial=!game||!Object.keys(game.board).length;if(next.revision!==lastRevision||!game){const draft=rebaseDraft(next.board,next.players[me].hand||[],pending);if(pending.length&&!draft.length&&!busy)toast('Masa değişti; denemeni yeniden düzenleyebilirsin.');pending=draft;selected=null;swapping=false;swapIds.clear();game=next;lastRevision=next.revision;if(next.revision===1){board.autoFit=true;board.camera={x:0,y:0,size:76};board.seen.clear()}if(view!=='game')setView('game');render();if(initial)requestAnimationFrame(()=>board.keepInView());else board.keepInView();celebrate()}else{game=next;render()}}else{game=null;if(view!=='lobby')setView('lobby');renderLobby()}}
