let layoutFrame;function adaptLayout(){const height=Math.round(window.visualViewport?.height||innerHeight),width=window.visualViewport?.width||innerWidth,roomy=width<=800&&height>=760&&height>width;document.documentElement.style.setProperty('--app-height',height+'px');document.body.dataset.layout=roomy?'roomy':'compact';const destination=roomy?$('lastMoveSlot'):document.querySelector('.board-status');if($('lastMove').parentElement!==destination)destination.append($('lastMove'))}function requestLayout(){cancelAnimationFrame(layoutFrame);layoutFrame=requestAnimationFrame(adaptLayout)}window.addEventListener('resize',requestLayout);window.visualViewport?.addEventListener('resize',requestLayout);adaptLayout();

