function openGames(){return read('renkio-open-games',[]).filter(g=>g.owner&&g.owner===accounts.profile?.id&&g.token)}
function storeOpenGames(games){const owner=accounts.profile?.id;const others=read('renkio-open-games',[]).filter(g=>g.owner&&g.owner!==owner);save('renkio-open-games',[...others,...games].slice(-100))}
function rememberRoom(v){if(!session||session.room!==v?.code||!v.game||v.seats[v.me]?.playerId!==accounts.profile?.id)return;if(v.game.over||v.game.players[v.me]?.eliminated){save('renkio-session',null);try{sessionStorage.removeItem('renkio-session')}catch{}}const entries=openGames().filter(g=>g.room!==v.code);if(!v.game.over&&!v.game.players[v.me]?.eliminated)entries.unshift({room:v.code,token:session.token,owner:accounts.profile?.id,updated:Date.now(),matchId:v.game.matchId,names:v.seats.filter((_,i)=>i!==v.me).map(p=>p.name),turn:v.game.turn===v.me,score:v.game.players[v.me].score,timeouts:v.game.timeoutCounts?.[v.me]||0,draft:pending,order:handOrder});storeOpenGames(entries)}
function renderOpenGames(){const entries=openGames(),solo=read('renkio-solo');$('resumePractice').classList.toggle('hidden',!solo?.game||solo.game.over||solo.game.players[0].eliminated);$('resume').classList.add('hidden');$('openGamesSection').classList.toggle('hidden',!entries.length);$('openGamesList').replaceChildren();
 const card=(label,detail,click,kind)=>{const b=node('button','open-game-card');const art=node('span','open-game-art');art.innerHTML=icon(kind||'people');const content=node('span','open-game-content');content.append(node('b','',label),node('small','',detail));b.append(art,content);b.insertAdjacentHTML('beforeend',icon('arrow'));b.onclick=()=>run(click);$('openGamesList').append(b)};
 for(const g of entries)card(g.names?.join(', ')||'Masa '+g.room,(g.turn?'Sıra sende':'Rakip oynuyor')+' · '+(g.score||0)+' puan'+(g.timeouts?' · '+g.timeouts+'/3':''),async()=>{const v=await api('state',g);connect({...v,token:g.token})});

}

async function refreshOpenGames(){const generation=++gamesRefresh;renderOpenGames();renderArchive();if(!accounts.profile)return;refreshFriends().catch(()=>{});refreshArchive().catch(()=>{});const owner=accounts.profile.id;try{const v=await api('games',{accountToken:await accounts.accountToken()},20000);if(generation!==gamesRefresh||owner!==accounts.profile?.id)return;storeOpenGames(mergeOpenGames(openGames(),v.games,owner));renderOpenGames()}catch{}}
$('refreshGames').onclick=()=>refreshOpenGames();
async function restoreRoomSession(){if(!session||!accounts.profile||openGames().some(g=>g.room===session.room))return;try{const candidate={...session},v=await api('state',candidate,12000);if(v.seats[v.me]?.playerId===accounts.profile.id&&v.game&&!v.game.over&&!v.game.players[v.me].eliminated){const entries=openGames();storeOpenGames([...entries,{...candidate,owner:accounts.profile.id,updated:Date.now(),matchId:v.game.matchId,names:v.seats.filter((_,i)=>i!==v.me).map(p=>p.name)}]);renderOpenGames()}}catch{}}

renderOpenGames();
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&view==='home')refreshOpenGames()});

setInterval(()=>{if(view==='home'&&document.visibilityState==='visible'&&navigator.onLine)refreshOpenGames()},15000);

function renderProfileButton(){const b=$('editAvatar');if(!b)return;b.replaceChildren(playerAvatar(accounts.profile?.name||'Sen',0,'',true),node('span','','Karakterini düzenle'))}
async function syncAvatar(){const id=accounts.profile?.id;if(!id)return;if(avatarSynced===id)return avatarSyncPromise;avatarSynced=id;avatarSyncPromise=(async()=>{const token=await accounts.accountToken();const remote=await api('profile',{accountToken:token},20000);if(accounts.profile?.id!==id)return;if(!hasAvatar()&&remote.avatar)saveAvatar(remote.avatar);else await api('avatar',{accountToken:token,avatar:readAvatar()},20000);renderProfileButton();if(game)render()})().catch(e=>{avatarSynced=null;throw e});return avatarSyncPromise}
function editAvatar(){closeDialogs();openAvatarPicker(async value=>{const token=await accounts.accountToken();await api('avatar',{accountToken:token,avatar:value},20000);saveAvatar(value);renderProfileButton();if(game)render()})}
$('editAvatar').onclick=editAvatar;
function archiveKey(){return 'renkio-matches:'+(accounts.profile?.id||'guest')}
function archived(){return read(archiveKey(),[])}
function mergeArchive(matches){const all=new Map(archived().map(m=>[m.id,m]));for(const m of matches)all.set(m.id,m);save(archiveKey(),[...all.values()].sort((a,b)=>b.at-a.at));renderArchive()}
function rememberCompleted(v){if(v.code==='solo'||!v.game?.over||!accounts.profile)return;v.game.matchId??=v.code==='solo'?'solo:'+soloAlertId:v.code+':legacy';if(v.seats[v.me]?.playerId!==accounts.profile.id)return;const record=matchRecord({...v,updated:Date.now()});if(record&&!archived().some(m=>m.id===record.id))mergeArchive([record])}
async function refreshArchive(){const id=accounts.profile?.id;if(!id)return;const result=await api('history',{accountToken:await accounts.accountToken()},20000);if(accounts.profile?.id===id)mergeArchive(result.matches)}
function renderArchive(){const host=$('matchArchiveList');if(!host)return;host.replaceChildren();const list=competitiveMatches(archived(),accounts.profile?.id);$('matchArchive').classList.toggle('hidden',!list.length);for(const m of list.slice(0,30)){const own=m.players.find(p=>p.id===accounts.profile?.id);if(!own)continue;const rivals=m.players.filter(p=>p!==own),b=node('button','saved-match'),label=node('span','',rivals.map(p=>p.name).join(', '));label.append(node('small','',new Date(m.at).toLocaleDateString('tr-TR')+' · '+(own.won?(m.players.filter(p=>p.won).length>1?'Berabere':'Kazandın'):'Kaybettin')));b.append(label,node('strong','',m.players.map(p=>p.score).join(' : ')));b.dataset.outcome=matchOutcome(m,accounts.profile?.id);b.onclick=()=>openMatch(m);host.append(b)}}
function profileDialog(title){closeDialogs();const d=document.createElement('dialog');d.className='profile-dialog';const top=node('div','drawer-heading'),close=node('button','icon-button');close.setAttribute('aria-label','Kapat');close.innerHTML=icon('close');close.onclick=()=>{d.close();d.remove()};top.append(node('h2','',title),close);d.append(top);d.addEventListener('cancel',()=>d.remove());document.body.append(d);d.showModal();return d}
function openMatch(m){const d=profileDialog('Maç geçmişi');for(const p of m.players){const b=node('button','saved-match'),label=node('span','',p.name);if(p.tag&&p.name!=='Player '+p.tag)label.append(node('small','','Player '+p.tag));b.append(playerAvatar(p.name,0,'',false,null,p.id),label,node('strong','',String(p.score)));b.onclick=()=>{d.close();d.remove();if(p.id===accounts.profile?.id)editAvatar();else openRival(p.id,p.name)};d.append(b)}const area=node('div','match-board-view'),content=node('div','match-board-content');content.innerHTML=finalBoardSvg(m.board);area.append(content);const controls=node('div','snapshot-controls');let zoom=1;for(const [glyph,label,factor]of [['minus','Tahtayı uzaklaştır',1/1.4],['target','Tahtayı sığdır',0],['plus','Tahtayı yakınlaştır',1.4]]){const b=node('button','icon-button');b.innerHTML=icon(glyph);b.setAttribute('aria-label',label);b.onclick=()=>{zoom=factor?Math.max(1,Math.min(12,zoom*factor)):1;content.style.width=zoom*100+'%';content.style.height=zoom*100+'%'};controls.append(b)}d.classList.add('match-detail-dialog');d.append(area,controls)}

async function openRival(id,name,value){const d=profileDialog(name);d.append(playerAvatar(name,0,'',false,value,id),node('small','',id==='miko'?'Miko':knownPlayerTag(id)?'Player '+knownPlayerTag(id):'Oyuncu profili'));const add=node('button','button button-purple full','Arkadaş ekle');add.classList.toggle('hidden',id==='miko'||!/^\d{12}$/.test(id));add.onclick=()=>requestFriend(id,add);d.append(add);const content=node('div');d.append(content);const draw=()=>{const stats=versus(competitiveMatches(archived(),accounts.profile?.id),accounts.profile?.id,id);content.replaceChildren();const cards=node('div','profile-stats');for(const [label,n]of [['Galibiyet',stats.wins],['Beraberlik',stats.draws],['Mağlubiyet',stats.losses]]){const c=node('div','profile-stat');c.append(node('b','',String(n)),node('small','',label));cards.append(c)}content.append(cards);if(!stats.games.length)content.append(node('p','','Henüz tamamlanan maçınız yok.'));for(const m of stats.games){const a=m.players.find(p=>p.id===accounts.profile?.id),b=m.players.find(p=>p.id===id),row=node('button','saved-match');row.append(node('span','',new Date(m.at).toLocaleDateString('tr-TR')),node('strong','',a.score+' : '+b.score));row.dataset.outcome=matchOutcome(m,accounts.profile?.id);row.onclick=()=>{d.close();d.remove();openMatch(m)};content.append(row)}};draw();try{await refreshArchive();if(d.open)draw()}catch{}}

function renderTimeoutDecision(){const d=$('timeoutDecision'),wait=$('timeoutWait'),decision=game?.timeoutDecision;wait.classList.toggle('hidden',!decision||decision.decider===me);if(!decision){if(d.open)d.close();return}if(decision.decider!==me){if(d.open)d.close();wait.textContent=game.players[decision.decider].name+' karar veriyor';return}$('timeoutPlayer').textContent=game.players[decision.actor].name+' üç kez süreyi aştı.';if(!d.open)modal('timeoutDecision')}
$('timeoutDecision').addEventListener('cancel',e=>e.preventDefault());
async function timeoutChoice(forfeit){if(!game?.timeoutDecision||game.timeoutDecision.decider!==me||busy)return;await run(async()=>{if(local){resolveTimeout(game,me,forfeit);lastRevision=game.revision;saveSolo();render();scheduleBot()}else receive(await api('timeout/resolve',{...session,revision:game.revision,forfeit}));sound.play(forfeit?'score':'drop')})}
$('continueTimeout').onclick=()=>timeoutChoice(false);$('claimTimeout').onclick=()=>timeoutChoice(true);
async function friendsApi(action='',extra={}){const token=await accounts.accountToken(),id=accounts.profile?.id,v=await api('friends'+action,{accountToken:token,...extra},20000);if(accounts.profile?.id!==id)return;friendsData=v;friendsOwner=id;save('renkio-friends:'+id,v);renderFriends();return v}
async function refreshFriends(){if(!accounts.profile)return;return friendsApi()}
function friendButton(iconName,label,fn){const b=node('button','icon-button');b.type='button';b.innerHTML=icon(iconName);b.title=label;b.setAttribute('aria-label',label);b.onclick=async()=>{b.disabled=true;try{await fn()}catch(e){toast(e.message,'error')}finally{b.disabled=false}};return b}
function friendRow(p){const r=node('div','friend-entry'),content=node('div','friend-name');content.append(node('b','',p.name),node('small','','Player '+(p.tag||'…')));const pic=playerAvatar(p.name,0,'',false,p.avatar,p.id);pic.tabIndex=0;pic.setAttribute('role','button');pic.setAttribute('aria-label',p.name+' · Profil');pic.onclick=()=>openRival(p.id,p.name,p.avatar);pic.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pic.click()}};r.append(pic,content);return r}
function renderFriends(){const badge=$('friendsButton');if(!badge)return;badge.classList.toggle('has-unread',!!(friendsData.incoming.length+friendsData.invites.length));$('myFriendId').textContent=accounts.profile?'Player '+(accounts.profile.tag||'…'):'';const list=$('friendsList');list.replaceChildren();const section=title=>list.append(node('h3','friend-heading',title));if(friendsData.invites.length){section('Davetler');for(const invite of friendsData.invites){const r=friendRow(invite.from);r.classList.add('friend-invite');r.append(friendButton('play','Masaya katıl',async()=>{const v=await api('join',{room:invite.room,...await accountPayload()});await friendsApi('/dismiss',{inviteId:invite.id});$('friendsDialog').close();connect(v)}),friendButton('close','Daveti kapat',()=>friendsApi('/dismiss',{inviteId:invite.id})));list.append(r)}}if(friendsData.incoming.length){section('İstekler');for(const p of friendsData.incoming){const r=friendRow(p);r.append(friendButton('check','İsteği kabul et',()=>friendsApi('/respond',{playerId:p.id,accept:true})),friendButton('close','İsteği reddet',()=>friendsApi('/respond',{playerId:p.id,accept:false})));list.append(r)}}if(friendsData.friends.length){section('Arkadaşların');for(const p of friendsData.friends){const r=friendRow(p);r.append(friendButton('people','Oyuna davet et',async()=>{let code=room&&!room.game&&view==='lobby'?room.code:null;if(!code){if(view!=='home')throw Error('Davet için ana menüye dön.');const v=await api('create',{...await accountPayload(),turnSeconds:0});$('friendsDialog').close();connect(v);code=v.code}await friendsApi('/invite',{playerId:p.id,room:code});sound.play('message');toast('Davet gönderildi.')}),friendButton('close','Arkadaşlıktan çıkar',async()=>{const d=profileDialog('Arkadaşlıktan çıkar?');d.append(node('p','',p.name));const b=node('button','button button-purple full','Çıkar');b.onclick=async()=>{b.disabled=true;try{await friendsApi('/remove',{playerId:p.id});d.close();d.remove()}catch(e){toast(e.message,'error');b.disabled=false}};d.append(b)}));list.append(r)}}if(friendsData.outgoing.length){section('Gönderilen istekler');for(const p of friendsData.outgoing){const r=friendRow(p);r.append(friendButton('close','İsteği geri çek',()=>friendsApi('/remove',{playerId:p.id})));list.append(r)}}$('friendsEmpty').classList.toggle('hidden',!!list.children.length)}
async function requestFriend(id,button){try{if(button)button.disabled=true;const v=await friendsApi('/request',{playerId:id});if(v?.incoming.some(p=>p.id===id||p.tag===id)){toast('Bu oyuncunun isteği Arkadaşlar’da bekliyor.')}else{sound.play('message');toast(v?.friends.some(p=>(p.id===id||p.tag===id))?'Zaten arkadaşsınız.':'Arkadaşlık isteği gönderildi.')}if(button)button.textContent=v?.friends.some(p=>(p.id===id||p.tag===id))?'Arkadaşsınız':v?.incoming.some(p=>(p.id===id||p.tag===id))?'İstek bekliyor':'İstek gönderildi'}catch(e){toast(e.message,'error');if(button)button.disabled=false}}
