function renderInventory(){if(!game)return;const counts=remainingTiles(game.board,game.players[me].hand||[]),body=$('inventoryRows');body.replaceChildren();let total=0;for(let c=0;c<6;c++){const row=node('tr');for(let s=0;s<6;s++){const count=counts[c][s];total+=count;const cell=node('td',count?'':'depleted');cell.setAttribute('aria-label',`${COLOR_NAMES[c]} ${SHAPE_NAMES[s]}: ${count}`);const symbol=node('span','inventory-symbol');symbol.innerHTML=`<svg viewBox="0 0 40 40" aria-hidden="true" fill="${COLORS[c]}"><path d="${SHAPE_PATHS[s]}"/></svg>`;cell.append(symbol,node('b','',String(count)));row.append(cell)}body.append(row)}$('inventoryTotal').textContent=total+' taş'}
$('bagButton').onclick=()=>{if(!game)return;renderInventory();modal('tileInventory')};

function scoreSparkles(){if(preferences.reduced||view!=='game'||chatIsOpen())return;const target=$('scoreBurst').getBoundingClientRect(),x=target.left+target.width/2,y=target.top+target.height/2;for(let i=0;i<8;i++){const dot=node('i','score-spark');dot.style.background=COLORS[i%6];dot.style.left=x+'px';dot.style.top=y+'px';document.body.append(dot);const angle=i*Math.PI/4,distance=24+Math.random()*22;dot.animate([{transform:'translate(-50%,-50%) scale(0)',opacity:0},{opacity:.8,offset:.18},{transform:`translate(calc(-50% + ${Math.cos(angle)*distance}px),calc(-50% + ${Math.sin(angle)*distance}px)) rotate(90deg) scale(.3)`,opacity:0}],{duration:460,easing:'ease-out'}).finished.catch(()=>{}).finally(()=>dot.remove())}}

